<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans, sans-serif;font-size:10px;color:#1f2937}h1{color:#065f46}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #d1d5db;padding:6px;text-align:left}th{background:#ecfdf5}small{color:#6b7280}</style></head><body><h1>Hope & Care Orphanage — Donations Report</h1><small>Generated {{ now()->format('d M Y H:i') }}</small><table><thead><tr><th>ID</th><th>Donor</th><th>Email</th><th>Amount</th><th>Currency</th><th>Method</th><th>Date</th></tr></thead><tbody>@foreach($rows as $row)<tr><td>{{ $row->id }}</td><td>{{ $row->name ?: 'Anonymous' }}</td><td>{{ $row->email }}</td><td>{{ number_format((float)$row->amount,2) }}</td><td>{{ $row->currency }}</td><td>{{ $row->payment_method }}</td><td>{{ optional($row->created_at)->format('d M Y') }}</td></tr>@endforeach</tbody></table></body></html>